insert into public.menus (id, name, ingredients, steps) values
  (1, 'ผัดเปรี้ยวหวาน', '[{"raw": "หอมใหญ่ 16.67 กรัม", "name": "หอมใหญ่"}, {"raw": "ซอสมะเขือเทศ 8.33 กรัม", "name": "ซอสมะเขือเทศ"}, {"raw": "ซอสพริกชนิดเผ็ดน้อย 4.33 กรัม", "name": "ซอสพริกชนิดเผ็ดน้อย"}, {"raw": "น้ำตาลทราย 1.33 กรัม", "name": "น้ำตาลทราย"}, {"raw": "ซอสถั่วเหลือง low sodium 4.33 กรัม", "name": "ซอสถั่วเหลือง low sodium"}, {"raw": "น้ำมันพืช 10 กรัม", "name": "น้ำมันพืช"}, {"raw": "แตงกวา 40 กรัม", "name": "แตงกวา"}, {"raw": "สับปะรดชนิดเปรี้ยว 23.33 กรัม", "name": "สับปะรดชนิดเปรี้ยว"}, {"raw": "เนื้อหมูสันนอกหั่นชิ้น 40 กรัม", "name": "เนื้อหมูสันนอกหั่นชิ้น"}, {"raw": "กระเทียมสับละเอียด 5 กรัม", "name": "กระเทียมสับละเอียด"}, {"raw": "รสดี รสหมู สูตรลดโซเดียม 0.33 กรัม", "name": "รสดี รสหมู สูตรลดโซเดียม"}, {"raw": "น้ำสะอาด 46.67 มิลลิลิตร", "name": "น้ำสะอาด"}, {"raw": "มะเขือเทศลูกใหญ่ 23.33 กรัม", "name": "มะเขือเทศลูกใหญ่"}]'::jsonb, '["1. ตั้งกระทะใช้ไฟกลาง ผัดกระเทียมกับน้ำมันจนเหลือง แล้วใส่หมูผัดจนสุก", "2. ใส่แตงกวา สับปะรด และหอมหัวใหญ่ คลุกให้เข้ากัน", "3. ปรุงรสด้วยซอสปรุงรสและรสดี เติมน้ำสะอาด คลุกให้เข้ากัน", "4. ใส่มะเขือเทศ ผัดให้เข้ากัน ปิดไฟและตักเสิร์ฟ"]'::jsonb),
  (2, 'ไก่เทริยากิ', '[{"raw": "สะโพกไก่ 280 กรัม", "name": "สะโพกไก่"}, {"raw": "งาขาวคั่ว 2 กรัม", "name": "งาขาวคั่ว"}, {"raw": "ต้นหอมซอย 2 กรัม", "name": "ต้นหอมซอย"}, {"raw": "ขิงซอย 5 กรัม", "name": "ขิงซอย"}, {"raw": "พริกไทยดำป่น 1 กรัม", "name": "พริกไทยดำป่น"}, {"raw": "ทาคูมิ อายิ ซอสเทริยากิ 20 กรัม", "name": "ทาคูมิ อายิ ซอสเทริยากิ"}, {"raw": "น้ำเปล่า 20 กรัม", "name": "น้ำเปล่า"}]'::jsonb, '["1. หมักสะโพกไก่ด้วยซอสเทริยากิและพริกไทย แล้วแช่เย็น", "2. คั่วงาขาวบนกระทะแห้ง", "3. ย่างไก่ที่หมักแล้วด้วยไฟกลางค่อนแรงจนสุก แล้วจัดเสิร์ฟ"]'::jsonb),
  (3, 'แกงส้มผักรวมปลา', '[{"raw": "ดอกกะหล่ำ 80 กรัม", "name": "ดอกกะหล่ำ"}, {"raw": "น้ำมะขามเปียก 180 กรัม", "name": "น้ำมะขามเปียก"}, {"raw": "น้ำเปล่า 700 กรัม", "name": "น้ำเปล่า"}, {"raw": "เนื้อปลานิล 320 กรัม", "name": "เนื้อปลานิล"}, {"raw": "หัวไชเท้า 160 กรัม", "name": "หัวไชเท้า"}, {"raw": "ถั่วฝักยาว 80 กรัม", "name": "ถั่วฝักยาว"}, {"raw": "พริกแกงส้ม 100 กรัม", "name": "พริกแกงส้ม"}, {"raw": "แครอท 40 กรัม", "name": "แครอท"}, {"raw": "กะปิ 10 กรัม", "name": "กะปิ"}, {"raw": "หอมแดงไทย 30 กรัม", "name": "หอมแดงไทย"}, {"raw": "พริกชี้ฟ้าแห้ง 16 กรัม", "name": "พริกชี้ฟ้าแห้ง"}, {"raw": "พริกจินดาสด 10 กรัม", "name": "พริกจินดาสด"}, {"raw": "กระชาย 30 กรัม", "name": "กระชาย"}, {"raw": "เนื้อปลานิลต้มสุก 60 กรัม", "name": "เนื้อปลานิลต้มสุก"}, {"raw": "อายิโนะโมะโต๊ะ 2 กรัม", "name": "อายิโนะโมะโต๊ะ"}, {"raw": "น้ำปลา 20 กรัม", "name": "น้ำปลา"}, {"raw": "น้ำตาลปื๊บ 24 กรัม", "name": "น้ำตาลปื๊บ"}]'::jsonb, '["1. ล้างปลาให้สะอาด", "2. โขลกพริกแกงกับเนื้อปลาให้แหลกเข้ากัน", "3. ละลายพริกแกงในน้ำเดือด ปรุงรสด้วยน้ำมะขาม อายิโนะโมะโต๊ะ และเครื่องปรุง", "4. ใส่ผักทั้งหมด ต้มจนเริ่มนิ่มและเดือด", "5. ตักเสิร์ฟเมื่อสุก"]'::jsonb),
  (4, 'ยำวุ้นเส้น', '[{"raw": "กุ้ง 45 กรัม", "name": "กุ้ง"}, {"raw": "หมูบด 45 กรัม", "name": "หมูบด"}, {"raw": "หมูยอ 45 กรัม", "name": "หมูยอ"}, {"raw": "ปลาหมึก 45 กรัม", "name": "ปลาหมึก"}, {"raw": "วุ้นเส้นแช่น้ำ 450 กรัม", "name": "วุ้นเส้นแช่น้ำ"}, {"raw": "น้ำมะนาว 30 กรัม", "name": "น้ำมะนาว"}, {"raw": "พริกขี้หนู 60 กรัม", "name": "พริกขี้หนู"}, {"raw": "น้ำปลา 10 กรัม", "name": "น้ำปลา"}, {"raw": "น้ำตาลทราย 15 กรัม", "name": "น้ำตาลทราย"}, {"raw": "อายิโนะโมะโต๊ะ 3 กรัม", "name": "อายิโนะโมะโต๊ะ"}, {"raw": "ขึ้นฉ่าย 15 กรัม", "name": "ขึ้นฉ่าย"}, {"raw": "หอมใหญ่ 120 กรัม", "name": "หอมใหญ่"}, {"raw": "มะเขือเทศ 120 กรัม", "name": "มะเขือเทศ"}]'::jsonb, '["1. ผสมพริกและเครื่องปรุงกับอายิโนะโมะโต๊ะเป็นน้ำยำ", "2. ลวกวุ้นเส้น หมูยอ และวัตถุดิบอื่น ๆ", "3. ใส่ทุกอย่างลงชาม ราดน้ำยำ คลุกให้เข้ากัน แล้วตักเสิร์ฟ"]'::jsonb),
  (5, 'ต้มเล้ง', '[{"raw": "กระดูกเล้ง 1500 กรัม", "name": "กระดูกเล้ง"}, {"raw": "น้ำเปล่า 2 ลิตร", "name": "น้ำเปล่า"}, {"raw": "รากผักชี 2 ราก", "name": "รากผักชี"}, {"raw": "กระเทียม 20 กรัม", "name": "กระเทียม"}, {"raw": "เกลือ 5 กรัม", "name": "เกลือ"}, {"raw": "พริกแดงจินดา 10 กรัม", "name": "พริกแดงจินดา"}, {"raw": "ผักชีฝรั่ง 10 กรัม", "name": "ผักชีฝรั่ง"}, {"raw": "พริกขี้หนูสวน 20 กรัม", "name": "พริกขี้หนูสวน"}, {"raw": "น้ำมะนาว 30 กรัม", "name": "น้ำมะนาว"}, {"raw": "น้ำปลา 15 กรัม", "name": "น้ำปลา"}, {"raw": "น้ำตาลทราย 3 กรัม", "name": "น้ำตาลทราย"}, {"raw": "อายิโนะโมะโต๊ะ 2 กรัม", "name": "อายิโนะโมะโต๊ะ"}]'::jsonb, '["1. ล้างกระดูกเล้งและต้มกับน้ำ ใส่รากผักชีและเกลือ", "2. เคี่ยวจนหมูเปื่อย แล้วใส่กระเทียม", "3. โขลกพริกและปรุงรสด้วยเครื่องปรุงกับอายิโนะโมะโต๊ะ", "4. เมื่อกระดูกเปื่อย ปิดไฟและตักเสิร์ฟ"]'::jsonb),
  (6, 'ราดหน้าเส้นใหญ่หมูหมัก', '[{"raw": "หมูสันนอก 150 กรัม", "name": "หมูสันนอก"}, {"raw": "ซอสถั่วเหลือง low sodium 1 ช้อนชา", "name": "ซอสถั่วเหลือง low sodium"}, {"raw": "ซอสหอยนางรม low sodium 1 ช้อนชา", "name": "ซอสหอยนางรม low sodium"}, {"raw": "พริกไทยป่น ¼ ช้อนชา", "name": "พริกไทยป่น"}, {"raw": "น้ำตาลทราย 1 ช้อนชา", "name": "น้ำตาลทราย"}, {"raw": "รสดี รสหมู สูตรลดโซเดียม ½ ช้อนชา", "name": "รสดี รสหมู สูตรลดโซเดียม"}, {"raw": "แป้งมัน ½ ช้อนชา", "name": "แป้งมัน"}, {"raw": "น้ำสะอาด ½ ช้อนโต๊ะ", "name": "น้ำสะอาด"}, {"raw": "เส้นใหญ่ 160 กรัม", "name": "เส้นใหญ่"}, {"raw": "คะน้า 100 กรัม", "name": "คะน้า"}, {"raw": "แครอท 40 กรัม", "name": "แครอท"}, {"raw": "น้ำมัน 1 ช้อนโต๊ะ", "name": "น้ำมัน"}, {"raw": "กระเทียม 1 ช้อนโต๊ะ", "name": "กระเทียม"}, {"raw": "เต้าเจี้ยว ¼ ช้อนโต๊ะ", "name": "เต้าเจี้ยว"}, {"raw": "น้ำตาลทราย 1 ช้อนโต๊ะ", "name": "น้ำตาลทราย"}, {"raw": "ซอสถั่วเหลือง low sodium 1 ช้อนโต๊ะ", "name": "ซอสถั่วเหลือง low sodium"}, {"raw": "ซอสหอยนางรม low sodium 1 ช้อนโต๊ะ", "name": "ซอสหอยนางรม low sodium"}, {"raw": "แป้งมัน 1 ช้อนโต๊ะ", "name": "แป้งมัน"}, {"raw": "น้ำสะอาด 1½ ถ้วยตวง", "name": "น้ำสะอาด"}]'::jsonb, '["1. หมักหมูกับเครื่องปรุงอย่างน้อย 30 นาทีหรือข้ามคืน", "2. แยกเส้นใหญ่และใส่ซีอิ๊วดำ", "3. ผสมน้ำราดกับเต้าเจี้ยว น้ำตาล ซอสปรุง รสดี และแป้งมัน", "4. ผัดเส้นใหญ่กับน้ำมันจนหอม", "5. ต้มหมูหมักกับคะน้าและแครอท แล้วใส่น้ำแป้งมัน"]'::jsonb),
  (7, 'ปลาราดซอสมะขาม', '[{"raw": "ปลาทับทิม 240 กรัม", "name": "ปลาทับทิม"}, {"raw": "น้ำมะขามเปียก 15 กรัม", "name": "น้ำมะขามเปียก"}, {"raw": "น้ำปลา 15 กรัม", "name": "น้ำปลา"}, {"raw": "น้ำตาลปี๊บ 30 กรัม", "name": "น้ำตาลปี๊บ"}, {"raw": "อายิโนะโมะโต๊ะ 3 กรัม", "name": "อายิโนะโมะโต๊ะ"}, {"raw": "น้ำสะอาด 45 มิลลิลิตร", "name": "น้ำสะอาด"}, {"raw": "หอมเจียว 30 กรัม", "name": "หอมเจียว"}, {"raw": "พริกแห้งทอด 15 กรัม", "name": "พริกแห้งทอด"}, {"raw": "น้ำมันถั่วเหลือง 30 กรัม", "name": "น้ำมันถั่วเหลือง"}]'::jsonb, '["1. ทอดปลาในน้ำมันร้อนจนเหลือง พักให้สะเด็ดน้ำมัน", "2. ผสมน้ำมะขาม น้ำปลา น้ำตาลปี๊บ และอายิโนะโมะโต๊ะ ตั้งไฟ", "3. เติมน้ำและเคี่ยวจนเข้ากัน", "4. ราดซอสบนปลา โรยหอมเจียวและพริกแห้งทอด"]'::jsonb),
  (8, 'แกงจืดหัวไชเท้า', '[{"raw": "กระดูกอ่อน 200 กรัม", "name": "กระดูกอ่อน"}, {"raw": "น้ำสะอาด 1 ลิตร", "name": "น้ำสะอาด"}, {"raw": "เกลือ 1 ช้อนชา", "name": "เกลือ"}, {"raw": "หัวไชเท้า 200 กรัม", "name": "หัวไชเท้า"}, {"raw": "เห็ดหอม 4 ดอก", "name": "เห็ดหอม"}, {"raw": "รสดีซุปก้อน รสหมู 1 ก้อน", "name": "รสดีซุปก้อน รสหมู"}, {"raw": "ซอสถั่วเหลือง 1 ช้อนโต๊ะ", "name": "ซอสถั่วเหลือง"}, {"raw": "น้ำตาลทราย 1 ช้อนชา", "name": "น้ำตาลทราย"}, {"raw": "ผักชี 5 กรัม", "name": "ผักชี"}]'::jsonb, '["1. ต้มน้ำ ใส่กระดูกหมูและเกลือ เคี่ยวประมาณ 30 นาที", "2. ใส่รสดีซุปก้อน หัวไชเท้า และเห็ดหอม เคี่ยวจนได้ที่", "3. ปรุงรสด้วยซอสถั่วเหลืองและน้ำตาล", "4. ตักเสิร์ฟและตกแต่งด้วยผักชี"]'::jsonb),
  (9, 'กระดูกหมูตุ๋นยาจีน', '[{"raw": "กระดูกอ่อน 75 กรัม", "name": "กระดูกอ่อน"}, {"raw": "น้ำสะอาด 600 มิลลิลิตร", "name": "น้ำสะอาด"}, {"raw": "เกลือ ลดโซเดียม 2 กรัม", "name": "เกลือ ลดโซเดียม"}, {"raw": "รากผักชี 5 กรัม", "name": "รากผักชี"}, {"raw": "กระเทียมไทย 10 กรัม", "name": "กระเทียมไทย"}, {"raw": "พริกไทยขาว 2.5 กรัม", "name": "พริกไทยขาว"}, {"raw": "น้ำตาลทราย 2 กรัม", "name": "น้ำตาลทราย"}, {"raw": "เครื่องตุ๋นยาจีน ½ ชุด", "name": "เครื่องตุ๋นยาจีน"}, {"raw": "เยื่อไผ่ 25 กรัม", "name": "เยื่อไผ่"}, {"raw": "เห็ดหอมแห้ง 7.5 กรัม", "name": "เห็ดหอมแห้ง"}, {"raw": "ซอสถั่วเหลือง ลดโซเดียม 2 กรัม", "name": "ซอสถั่วเหลือง ลดโซเดียม"}, {"raw": "รสดี รสหมู สูตรลดโซเดียม 4 กรัม", "name": "รสดี รสหมู สูตรลดโซเดียม"}, {"raw": "ผักชี 4 กรัม", "name": "ผักชี"}]'::jsonb, '["1. ล้างกระดูกแล้วต้มไฟแรงกับรากผักชี กระเทียม และพริกไทย", "2. ใส่เยื่อไผ่และเห็ดหอมที่แช่น้ำแล้ว เคี่ยวรวมกัน", "3. ปรุงรสด้วยซอสถั่วเหลือง น้ำตาล น้ำปลา และรสดี", "4. ปิดไฟ ตักใส่ภาชนะและโรยผักชี"]'::jsonb),
